J('trainee', 'buero', 'Traineeprogramm',
  'trainee traineeprogramm berufseinstieg absolvent hochschulabsolvent management nachwuchs rotation bewerbung',
  'Nach dem Studium: Rotation durch mehrere Abteilungen.',
  'Bewerbung für ein Traineeprogramm nach dem Studium: Muster-Anschreiben für Wirtschaftsabsolventin, Ingenieur und Geisteswissenschaftlerin, mit Lebenslauf und Tipps.',
  'Traineeprogramme dauern meist zwölf bis 24 Monate, du durchläufst mehrere Abteilungen und bekommst ein eigenes Projekt. Unternehmen suchen Absolventinnen und Absolventen, die Orientierung mit Richtung verbinden: offen für vieles, aber mit einer Idee, wohin es gehen soll. Praktika und Auslandserfahrung zählen.',
  ['Abgeschlossenes Studium (Bachelor oder Master)', 'Praktika oder Werkstudentenjobs', 'Mobilität für Stationen an anderen Standorten', 'Interesse an der Branche, nicht nur am Programm', 'Englisch, oft verhandlungssicher'],
  [L('Wirtschaftsabsolventin mit Logistikfokus', 'berufseinstieg', 'Trainee Supply Chain Management',
     T('Weserfracht Gruppe', 'f', 'Kühl', 'Überseestadt 12', '28217 Bremen'),
     ['wie kommt eine Tonne Kaffee aus Kolumbien in eine Rösterei in Bremen? In meiner Masterarbeit habe ich diesen Weg für einen Importeur nachgezeichnet, mit allen Übergaben, Wartezeiten und Kosten. Am Ende stand ein Vorschlag, der die Lagerzeit im Hafen um vier Tage verkürzt. Seitdem weiß ich, wohin ich beruflich will.',
      'Ich habe Wirtschaftsingenieurwesen in Bremen studiert und im März meinen Master abgeschlossen. Zwei Praktika, eines in der Disposition eines Spediteurs und eines im Einkauf eines Lebensmittelherstellers, haben mir beide Seiten der Lieferkette gezeigt. Ihr Programm mit Stationen in Bremen, Rotterdam und Singapur würde mir die dritte zeigen.',
      'Englisch spreche ich verhandlungssicher, Niederländisch lerne ich gerade. Ich bin ab Juni verfügbar.'],
     ['Lebenslauf', 'Masterzeugnis', 'Praktikumszeugnisse']),
   L('Ingenieur, der in den Vertrieb will', 'berufseinstieg', 'Trainee Technischer Vertrieb',
     T('Kältetechnik Nord AG', 'm', 'Reimers', 'Am Wall 140', '28195 Bremen'),
     ['in meinen Praktika war ich immer dann am besten, wenn ich Technik erklären musste. Bei einem Kundentermin mit einem Supermarktbetreiber habe ich unserem Vertriebsleiter geholfen, die Vorteile einer neuen Kühlanlage verständlich zu machen, und er hat mich danach gefragt, ob ich mir den Vertrieb vorstellen kann. Ja, kann ich.',
      'Ich habe Maschinenbau mit Schwerpunkt Energietechnik studiert, Bachelor 2024, Master 2026. Kältetechnik war Thema meiner Masterarbeit. Ihr Traineeprogramm verbindet ein halbes Jahr in Entwicklung und Service mit einem Jahr im Vertrieb, und das finde ich genau richtig.',
      'Reisebereitschaft bringe ich mit, Führerschein habe ich.'],
     ['Lebenslauf', 'Masterzeugnis', 'Bachelorzeugnis'],
     ['Hendrik Oltmanns', 'Bismarckstraße 50', '28203 Bremen']),
   L('Geisteswissenschaftlerin für Kommunikation', 'berufseinstieg', 'Trainee Unternehmenskommunikation',
     T('Hanseatische Energieversorgung', 'none', '', 'Theodor-Heuss-Allee 20', '28215 Bremen'),
     ['Geschichte zu studieren heißt, Quellen kritisch zu lesen und komplizierte Zusammenhänge so zu erklären, dass andere sie verstehen. In der Energiewende brauchen Unternehmen genau das: Mit Bürgern sprechen, die Angst vor höheren Preisen haben, und mit Journalisten, die schnelle Antworten wollen.',
      'Neben dem Master habe ich drei Jahre als Werkstudentin in der Pressestelle der Universität gearbeitet, Pressemitteilungen geschrieben und den Newsletter betreut. Ein Praktikum bei einer Lokalzeitung hat mir gezeigt, wie die andere Seite arbeitet.',
      'Ihr Programm mit Stationen in Pressestelle, interner Kommunikation und Public Affairs würde mir die Breite geben, die ich suche.'],
     ['Lebenslauf', 'Masterzeugnis', 'Arbeitsproben'],
     ['Charlotte Wendt', 'Am Dobben 70', '28203 Bremen'])],
  CV('a14', 'modern', 0, 'Aylin Doğan', 'M. Sc. Wirtschaftsingenieurwesen', 'Buntentorsteinweg 200', '28201 Bremen',
     [row('04/2025', '09/2025', 'Praktikantin Disposition', 'Spedition Hanse Cargo', 'Bremen', '- Tourenplanung, Zollpapiere\n- Auswertung von Laufzeiten'),
      row('10/2023', '03/2024', 'Praktikantin Einkauf', 'Feinkost Weser GmbH', 'Bremen', '- Lieferantenvergleich, Bestellungen'),
      row('2022', '2025', 'Werkstudentin Controlling', 'Universität Bremen', 'Bremen', '')],
     [row('2024', '2026', 'Wirtschaftsingenieurwesen (M. Sc.), Note 1,6', 'Universität Bremen', 'Bremen', 'Masterarbeit: Lieferkette Rohkaffee – Verkürzung der Hafenliegezeit'),
      row('2020', '2024', 'Wirtschaftsingenieurwesen (B. Sc.)', 'Hochschule Bremen', 'Bremen', '')],
     [['Supply Chain Analyse', 4], ['Tabellenkalkulation', 5], ['Projektmanagement', 3], ['Präsentation', 4]],
     [DE, ['Türkisch', 'native'], ['Englisch', 'C1'], ['Niederländisch', 'A2']], 'Segeln, Kaffeerösten'),
  ['Gewünschten Bereich nennen, auch wenn das Programm rotiert.', 'Praktika mit Ergebnis beschreiben.', 'Mobilität ansprechen.'],
  ['Nur das Programm loben.', 'Noten seitenlang erklären.', 'Sich für fünf Traineeprogramme mit demselben Text bewerben.'],
  ['Warum ein Traineeprogramm und kein Direkteinstieg?', 'Welche Station interessiert Sie am meisten?', 'Wie gehen Sie mit Ortswechseln um?', 'Wo sehen Sie sich nach dem Programm?'],
  [Q('Trainee oder Direkteinstieg?', 'Trainees lernen das Unternehmen breit kennen und bekommen oft Mentoring. Beim Direkteinstieg bist du schneller in einer festen Rolle. Für Absolventen, die sich noch orientieren, ist ein Traineeprogramm ein guter Weg.')],
  ['duales-studium-bwl', 'projektmanager', 'controller', 'marketing-manager'])

J('teamleiter', 'buero', 'Teamleiter/in',
  'teamleiter teamleiterin teamleitung führungskraft gruppenleiter erste führungsposition kundenservice bewerbung',
  'Erste Führungsposition oder Wechsel als erfahrene Teamleitung.',
  'Bewerbung als Teamleiter/in: Muster-Anschreiben für den ersten Schritt in die Führung, für erfahrene Teamleitung und für eine interne Bewerbung, mit Lebenslauf.',
  'Teamleitungen verantworten Menschen und Ergebnisse. In der Bewerbung zählt, wie du führst: Wie viele Leute, welche Ziele, welche Schwierigkeiten? Erzähl von einer Situation, in der du ein Team durch etwas gebracht hast. Zahlen helfen, aber auch der Umgang mit Konflikten.',
  ['Fachliche Erfahrung im Bereich', 'Erste Führungserfahrung (auch stellvertretend, Projekte, Azubis)', 'Klare Kommunikation', 'Umgang mit Kennzahlen', 'Konfliktfähigkeit'],
  [L('Sachbearbeiter wird erstmals Teamleiter', 'erfahren', 'Teamleiter Kundenservice',
     T('Energieversorgung Saarbrücken-West GmbH', 'f', 'Klein', 'Am Kraftwerk 4', '66117 Saarbrücken'),
     ['unsere Teamleiterin vertrete ich seit zwei Jahren, wenn sie im Urlaub oder krank ist. In dieser Zeit verteile ich die Anfragen auf acht Kolleginnen und Kollegen, führe die Kurzbesprechung am Morgen und springe ein, wenn ein Kunde nur mit „jemandem von oben“ sprechen will. Jetzt möchte ich den Schritt ganz machen.',
      'Im Kundenservice eines Energieversorgers arbeite ich seit sieben Jahren, die meisten davon im Bereich Abrechnung und Beschwerden. Letztes Jahr habe ich ein Projekt geleitet, das die Bearbeitungszeit für Abschlagsänderungen von neun auf drei Tage gesenkt hat. Dafür habe ich mit IT und Abrechnung zusammengearbeitet, ohne dass mir jemand unterstellt war.',
      'Führung lerne ich gerade auch formal: Ich besuche einen Kurs für neue Führungskräfte bei der IHK. Ein Gespräch mit Ihnen wäre mir wichtig.'],
     ['Lebenslauf', 'Zwischenzeugnis', 'Teilnahmebestätigung Führungskurs']),
   L('Erfahrene Teamleiterin wechselt die Branche', 'erfahren', 'Teamleiterin Auftragsabwicklung',
     T('Saar-Elektronik GmbH', 'm', 'Becker', 'Am Torhaus 3', '66113 Saarbrücken'),
     ['ein Team von zwölf Leuten im Versandhandel habe ich fünf Jahre lang geführt, durch zwei Weihnachtsgeschäfte mit dreifachem Auftragsvolumen und einen Systemwechsel, den keiner wollte. Die Fluktuation im Team lag am Ende bei unter fünf Prozent, im Haus bei 18.',
      'Ich möchte in die Industrie wechseln, weil mich die engere Verbindung zu Produktion und Kunden reizt. Bei Ihnen läuft Auftragsabwicklung direkt mit Fertigung und Technik zusammen, das ist anspruchsvoller als im Handel, aber auch spannender. Mitarbeitergespräche, Zielvereinbarungen und Personaleinsatzplanung gehören für mich zum Alltag.',
      'Meine Kündigungsfrist beträgt drei Monate.'],
     ['Lebenslauf', 'Arbeitszeugnisse'],
     ['Melanie Hoffmann', 'Mainzer Straße 80', '66121 Saarbrücken']),
   L('Interne Bewerbung auf die Nachfolge', 'erfahren', 'Teamleitung Lager (interne Bewerbung)',
     T('Logistikzentrum Saarlouis, Personalabteilung', 'm', 'Weber', 'Am Hafen 1', '66740 Saarlouis'),
     ['Herr Schmitt geht im Herbst in Rente, und ich möchte mich um seine Nachfolge als Teamleiter im Wareneingang bewerben. Nach neun Jahren bei uns, davon vier als Vorarbeiter, kenne ich das Team, die Abläufe und die Schwachstellen.',
      'Als Vorarbeiter teile ich die Schichten ein, arbeite Neue ein und bin Ansprechpartner, wenn Lieferanten zu spät kommen. Den Ausbilderschein habe ich, und ich habe drei Azubis bis zur Prüfung begleitet. Was ich noch lernen muss, sind Budgetplanung und Kennzahlenberichte; dafür würde ich gern die interne Führungskräfteschulung besuchen.',
      'Ein Gespräch zu dritt mit Herrn Schmitt wäre ideal.'],
     ['Lebenslauf', 'Ausbildereignung'],
     ['Andreas Biehl', 'Lisdorfer Straße 22', '66740 Saarlouis'])],
  CV('a12', 'classic', 5, 'Patrick Schwarz', 'Sachbearbeiter Kundenservice, stellv. Teamleiter', 'Dudweilerstraße 50', '66111 Saarbrücken',
     [row('04/2019', '', 'Sachbearbeiter Kundenservice, ab 2024 stellv. Teamleiter', 'Energieversorgung Saar', 'Saarbrücken', '- Vertretung der Teamleitung (8 Personen)\n- Projektleitung: Bearbeitungszeit Abschlagsänderungen von 9 auf 3 Tage\n- Eskalationsfälle und Beschwerdemanagement'),
      row('09/2016', '03/2019', 'Kaufmann für Büromanagement', 'Autohaus Rathke', 'Saarbrücken', '')],
     [row('2013', '2016', 'Ausbildung Kaufmann für Büromanagement', 'Autohaus Rathke', 'Saarbrücken', '')],
     [['Teamkoordination', 4], ['Beschwerdemanagement', 5], ['Prozessverbesserung', 4], ['Kennzahlen', 3]],
     [DE, ['Französisch', 'B2'], ['Englisch', 'B1']], 'Laufen, Kochen', courses=[row('', '2026', 'Lehrgang Neue Führungskräfte', 'IHK Saarland')]),
  ['Teamgröße und Verantwortung nennen.', 'Ein Beispiel für Führung in schwierigen Zeiten.', 'Ehrlich sagen, was du noch lernst.'],
  ['„Ich führe kooperativ“ ohne Beispiel.', 'Erfolge des Teams als eigene darstellen.', 'Den bisherigen Chef schlechtmachen.'],
  ['Wie führen Sie ein Gespräch mit einem Mitarbeiter, der nachlässt?', 'Wie sind Sie mit Ihrem schwierigsten Konflikt umgegangen?', 'Wie würden Sie Ihre ersten 100 Tage gestalten?', 'Wie gehen Sie damit um, Vorgesetzter früherer Kollegen zu werden?'],
  [Q('Ich habe keine offizielle Führungserfahrung – kann ich mich trotzdem bewerben?', 'Ja, wenn du zeigen kannst, dass du schon geführt hast: Vertretungen, Projektleitung, Azubis betreut, Schichten eingeteilt. Beschreib das konkret und sag, wie du dich auf die Rolle vorbereitest.')],
  ['projektmanager', 'schichtleiter', 'filialleiter', 'kundenservice-mitarbeiter'],
  en=EN('team-leader', 'Team leader', 'team leader supervisor first management role line manager customer service',
        'Your first leadership role, or a move as an experienced team leader.',
        'Team leader cover letter examples: a first step into management and an experienced team leader changing sector, plus a ready CV with placeholder portrait.',
        'Team leaders are responsible for people and results. Say how many people you have led, what changed under your lead and how you handle conflict. Numbers help, but so does one honest story.',
        ['Experience in the area you will lead', 'Some leadership: acting up, projects, training new starters', 'Clear communication', 'Comfortable with targets and data', 'Handling conflict fairly'],
        [L('Stepping up into a first team leader role', 'erfahren', 'Customer service team leader',
           T('Severn Water Services', 'f', 'Evans', 'Unit 4, Riverside Park', 'Cardiff CF10 5BZ'),
           ['for the last two years I have covered for my team leader whenever she is away. That means allocating work across eight colleagues, running the morning huddle and taking the calls from customers who insist on speaking to “someone senior”. I would now like to take on the role properly.',
            'I have worked in customer service for seven years, mostly on billing and complaints. Last year I led a small project with our IT and billing teams that cut the time to change a payment plan from nine days to three, without anyone reporting to me.',
            'I am currently completing a first-line management course. I would value the chance to talk to you.'],
           ['CV', 'Course details']),
         L('Experienced team leader moving into manufacturing', 'erfahren', 'Order management team leader',
           T('Cambrian Electronics Ltd', 'm', 'Davies', 'Pontprennau Business Park', 'Cardiff CF23 8RS'),
           ['five years leading a team of twelve in online retail have taken me through two peak seasons at triple volume and a system change nobody asked for. Staff turnover in my team ended up under five per cent; across the site it was eighteen.',
            'I want to move into manufacturing because order management there sits much closer to production and engineering. One-to-ones, objectives and rota planning are part of my normal week. My notice period is three months.'],
           ['CV', 'References'],
           ['Rachel Hughes', '18 Albany Road', 'Cardiff CF24 3RQ'])],
        CV('a12', 'classic', 5, 'Owen Price', 'Customer service adviser, deputy team leader', '50 Crwys Road', 'Cardiff CF24 4NN',
           [row('04/2019', '', 'Customer service adviser, deputy team leader from 2024', 'Valleys Energy', 'Cardiff', '- Acting team leader (8 people)\n- Led project: payment plan changes from 9 to 3 days\n- Complaints and escalations'),
            row('09/2016', '03/2019', 'Office administrator', 'Bay Motors', 'Cardiff', '')],
           [row('2014', '2016', 'Business administration apprenticeship', 'Cardiff and Vale College', 'Cardiff', '')],
           [['Team coordination', 4], ['Complaint handling', 5], ['Process improvement', 4], ['Reporting', 3]],
           [['English', 'native'], ['Welsh', 'B1']], 'Running, cooking', courses=[row('', '2026', 'First-line management course')]),
        ['Give team size and responsibilities.', 'Describe leading through a difficult period.', 'Say honestly what you are still learning.'],
        ['Claim a “collaborative style” without an example.', 'Present team results as yours alone.', 'Criticise your current manager.'],
        ['How would you handle a team member whose performance has dropped?', 'Tell us about a difficult conflict.', 'What would your first 100 days look like?', 'How will you manage former peers?'],
        [Q('I have never officially managed anyone – can I still apply?', 'Yes, if you can show leadership: acting up, leading projects, training new starters, planning rotas. Describe it concretely and explain how you are preparing for the role.')]))

J('projektmanager', 'buero', 'Projektmanager/in',
  'projektmanager projektmanagerin projektleiter projektleitung pm scrum agil wasserfall zertifizierung bewerbung',
  'Projekte steuern – in IT, Bau, Industrie oder Agentur.',
  'Bewerbung als Projektmanager/in: Muster-Anschreiben für erfahrene Projektleiterin, Quereinsteiger aus der Technik und Berufseinsteigerin, mit Lebenslauf und Interviewfragen.',
  'Projektmanagerinnen und -manager halten Zeit, Budget und Qualität im Gleichgewicht und bringen Leute zusammen, die nicht an sie berichten. In der Bewerbung zählen Projekte mit Umfang, Rolle und Ergebnis. Zertifikate helfen, ersetzen aber keine Erfahrung.',
  ['Projekterfahrung mit Budget- und Terminverantwortung', 'Methodenkenntnis (klassisch, agil, hybrid)', 'Stakeholder-Management', 'Strukturierte Kommunikation', 'Branchenkenntnis'],
  [L('Projektleiterin mit Erfahrung im Bau', 'erfahren', 'Projektmanagerin Bau (Schulbau)',
     T('Kreisbau Ortenau GmbH', 'm', 'Huber', 'Badstraße 20', '77652 Offenburg'),
     ['drei Schulerweiterungen habe ich in den letzten fünf Jahren als Projektleiterin bei einem Generalunternehmer betreut, die größte mit einem Volumen von zwölf Millionen Euro. Alle drei wurden zum Schuljahresbeginn fertig, einmal mit zwei Wochenenden Sonderschicht, über die ich heute noch mit dem Polier lache.',
      'Ich möchte die Seite wechseln und als Bauherrenvertreterin arbeiten. Ich kenne die Probleme der ausführenden Firmen und weiß, welche Informationen sie wann brauchen. Ausschreibungen nach VOB, Nachtragsmanagement und Terminplanung sind mein Alltag.',
      'Ich bin Bauingenieurin (M. Sc.) und lebe in Offenburg. Kündigungsfrist: drei Monate zum Quartalsende.'],
     ['Lebenslauf', 'Masterzeugnis', 'Arbeitszeugnis', 'Projektliste']),
   L('Techniker wird Projektmanager', 'quereinstieg', 'Projektmanager Anlagenbau',
     T('Schwarzwald Anlagentechnik GmbH', 'none', '', 'Industriestraße 45', '77656 Offenburg'),
     ['Inbetriebnahmen im Ausland sind seit acht Jahren mein Job. In dieser Zeit habe ich gesehen, welche Projekte gut laufen und welche nicht, und fast immer lag es nicht an der Technik, sondern an Abstimmung, Planung und Erwartungen. Daran möchte ich künftig arbeiten.',
      'Als Servicetechniker habe ich Teams von bis zu sechs Leuten auf Baustellen in Polen, Mexiko und Indien koordiniert, Tagesberichte geschrieben, Änderungen mit Kunden verhandelt und Mängellisten abgearbeitet. Eine Zertifizierung im Projektmanagement habe ich im letzten Jahr berufsbegleitend erworben.',
      'Ich spreche Englisch fließend, Spanisch gut, und Reisen schreckt mich nicht ab, wenn es nicht mehr 200 Tage im Jahr sind.'],
     ['Lebenslauf', 'Zertifikat Projektmanagement', 'Arbeitszeugnis'],
     ['Michael Lehmann', 'Hauptstraße 7', '77704 Oberkirch']),
   L('Berufseinsteigerin aus dem Studium', 'berufseinstieg', 'Junior-Projektmanagerin',
     T('Digitalagentur Rheinblick', 'f', 'Zimmer', 'Kinzigstraße 10', '77652 Offenburg'),
     ['in meinem Praktikum bei einer Agentur in Freiburg hat mich die Projektleiterin nach drei Wochen gefragt, ob ich das Kundenprojekt für eine Bäckereikette mitbetreuen will. Ich habe Protokolle geschrieben, Aufgaben im Board gepflegt, den Kunden an Freigaben erinnert und am Ende den Launch mitorganisiert.',
      'Im Februar habe ich meinen Bachelor in Medienmanagement abgeschlossen. Ich arbeite gern strukturiert, bin aber nicht dogmatisch, was Methoden angeht. Ihre Agentur betreut viele mittelständische Kunden aus der Region, für die Digitales neu ist; das stelle ich mir als besonders lohnend vor.',
      'Ich kann sofort anfangen.'],
     ['Lebenslauf', 'Bachelorzeugnis', 'Praktikumszeugnis'],
     ['Mira Lang', 'Okenstraße 30', '77652 Offenburg'])],
  CV('a23', 'classic', 0, 'Katrin Bühler', 'Bauingenieurin (M. Sc.), Projektleiterin', 'Wilhelmstraße 18', '77654 Offenburg',
     [row('03/2021', '', 'Projektleiterin', 'Generalbau Baden GmbH', 'Freiburg', '- Drei Schulerweiterungen, bis 12 Mio. Euro Volumen\n- Termin- und Kostensteuerung, Nachtragsmanagement\n- Führung von Bauleitern und Nachunternehmern'),
      row('10/2017', '02/2021', 'Bauleiterin', 'Hochbau Kaiser', 'Lahr', '- Wohnungsbau, Bauüberwachung')],
     [row('2015', '2017', 'Bauingenieurwesen (M. Sc.)', 'Karlsruher Institut für Technologie', 'Karlsruhe', ''),
      row('2011', '2015', 'Bauingenieurwesen (B. Eng.)', 'Hochschule Karlsruhe', 'Karlsruhe', '')],
     [['Terminplanung', 5], ['VOB und Ausschreibung', 4], ['Kostensteuerung', 4], ['Verhandlung', 4]],
     [DE, ['Englisch', 'B2'], ['Französisch', 'B1']], 'Wandern, Chor'),
  ['Projekte mit Umfang, Dauer, Rolle und Ergebnis.', 'Methoden nennen, die du angewendet hast.', 'Zeigen, wie du mit Stakeholdern umgehst.'],
  ['Zertifikate als Hauptargument.', 'Nur Erfolge, keine Lernmomente.', 'Fachbegriffe ohne Inhalt.'],
  ['Was war Ihr schwierigstes Projekt?', 'Wie gehen Sie mit Scope Creep um?', 'Wann ist ein Projekt für Sie erfolgreich?', 'Wie führen Sie Menschen, die Ihnen nicht unterstellt sind?'],
  [Q('Brauche ich ein Zertifikat?', 'Nicht zwingend. Viele Arbeitgeber schätzen Zertifizierungen, entscheidend sind aber Projekterfahrung und Ergebnisse. Für den Quereinstieg kann ein Zertifikat helfen, deine Kenntnisse nachzuweisen.')],
  ['teamleiter', 'it-projektleiter', 'trainee', 'office-manager'],
  en=EN('project-manager', 'Project manager', 'project manager project lead pm agile delivery construction engineering',
        'Delivering projects in construction, engineering, IT or agencies.',
        'Project manager cover letter examples: an experienced construction project lead and an engineer moving into project management, plus a ready CV.',
        'Project managers balance time, budget and quality and bring together people who do not report to them. Show projects with scope, your role and the outcome. Certificates help but do not replace experience.',
        ['Projects with budget and schedule responsibility', 'Knowledge of methods (traditional, agile, hybrid)', 'Stakeholder management', 'Structured communication', 'Sector knowledge'],
        [L('Construction project lead moving to the client side', 'erfahren', 'Project manager (school buildings)',
           T('County Estates Department', 'm', 'Hughes', 'County Hall, Main Street', 'Taunton TA1 4DY'),
           ['three school extensions in five years, the largest worth twelve million pounds: all of them were handed over before the start of term, one after two weekends of extra shifts that the site manager and I still joke about.',
            'I would now like to move to the client side. I know what contractors struggle with and what information they need, and when. Tendering, change control and programme management are my daily work. I am a chartered civil engineer and live locally.'],
           ['CV', 'Project list']),
         L('Field engineer moving into project management', 'quereinstieg', 'Project manager (industrial equipment)',
           T('Westcountry Process Systems', 'none', '', 'Unit 9, Marsh Barton', 'Exeter EX2 8NP'),
           ['commissioning jobs abroad have been my work for eight years. I have seen which projects go well and which do not, and it is rarely the engineering. It is planning, coordination and expectations, and that is where I want to work now.',
            'As a field engineer I have coordinated teams of up to six on sites in Poland, Mexico and India, written daily reports, agreed changes with clients and worked through snag lists. Last year I gained a project management qualification part time.',
            'Travel does not put me off, as long as it is no longer 200 days a year.'],
           ['CV', 'Qualification certificate'],
           ['Michael Lane', '7 High Street', 'Crediton EX17 3AH'])],
        CV('a23', 'classic', 0, 'Kate Bailey', 'Chartered civil engineer, project lead', '18 Wellington Road', 'Taunton TA1 4EH',
           [row('03/2021', '', 'Project lead', 'Southwest Build Ltd', 'Bristol', '- Three school extensions up to £12m\n- Programme and cost control, change management'),
            row('10/2017', '02/2021', 'Site engineer', 'Kaiser Construction', 'Exeter', '')],
           [row('2013', '2017', 'MEng Civil Engineering', 'University of Bath', 'Bath', '')],
           [['Programme planning', 5], ['Tendering and contracts', 4], ['Cost control', 4], ['Negotiation', 4]],
           [['English', 'native'], ['French', 'B1']], 'Hiking, choir'),
        ['Give scope, duration, role and outcome.', 'Name the methods you have actually used.', 'Show how you handle stakeholders.'],
        ['Lead with certificates.', 'Only list successes, no lessons.', 'Use jargon without substance.'],
        ['What was your hardest project?', 'How do you deal with scope creep?', 'When is a project successful?', 'How do you lead people who do not report to you?'],
        [Q('Do I need a certificate?', 'Not necessarily. Many employers value certifications, but experience and results decide. If you are changing career, a certificate can help prove your knowledge.')]))

J('office-manager', 'buero', 'Office-Manager/in',
  'office manager officemanagerin büroleitung büromanagement verwaltung startup assistenz bewerbung',
  'Büro organisieren – vom Einkauf bis zum Onboarding.',
  'Bewerbung als Office-Manager/in: Muster-Anschreiben für erfahrene Assistentin, Rezeptionist mit Aufstiegswunsch und Wiedereinsteigerin, mit Lebenslauf.',
  'Office-Managerinnen und -Manager halten den Laden zusammen: Einkauf, Dienstleister, Reisen, Veranstaltungen, Onboarding, oft auch Buchhaltungsvorbereitung und HR-Unterstützung. Gefragt ist jemand, der Dinge erledigt, bevor jemand fragt. Beschreib, was du organisiert hast und wie viele Leute davon profitiert haben.',
  ['Kaufmännische Ausbildung oder Erfahrung im Büro', 'Organisationstalent und Überblick', 'Sicherer Umgang mit Office-Programmen', 'Freundlich, aber bestimmt im Umgang mit Dienstleistern', 'Diskretion'],
  [L('Assistentin übernimmt das ganze Büro', 'erfahren', 'Office-Managerin',
     T('Softwarehaus Elbhang GmbH', 'f', 'Pohl', 'Schillerplatz 9', '01309 Dresden'),
     ['als ich bei meinem jetzigen Arbeitgeber anfing, waren wir 18 Leute in einer Etage. Heute sind es 65 an zwei Standorten, und ich habe beide Umzüge organisiert, die Küche ausgestattet, einen Rahmenvertrag mit der Reinigungsfirma ausgehandelt und ein Onboarding-Paket gebaut, das jeder Neue am ersten Tag auf dem Tisch hat.',
      'Gelernt habe ich Kauffrau für Büromanagement, seitdem arbeite ich seit elf Jahren in Assistenz und Office-Management. Rechnungen vorkontieren, Reisen buchen, Weihnachtsfeiern für 80 Personen planen und die Geschäftsführung entlasten gehören zu meinem Alltag. Ich möchte nun in einem Unternehmen arbeiten, das wie Ihres gerade wächst und jemanden braucht, der Strukturen aufbaut.',
      'Meine Kündigungsfrist beträgt drei Monate.'],
     ['Lebenslauf', 'Arbeitszeugnisse', 'Abschlusszeugnis']),
   L('Empfangsmitarbeiter mit Aufstiegswunsch', 'erfahren', 'Office-Manager (Teilzeit, 30 Stunden)',
     T('Kanzlei Weber Rechtsanwälte', 'm', 'Weber', 'Prager Straße 2', '01069 Dresden'),
     ['seit vier Jahren sitze ich am Empfang eines Coworking-Hauses. In dieser Zeit habe ich mehr übernommen, als in meiner Stellenbeschreibung steht: Raumbuchungen, Wartungsverträge, Getränkebestellungen, das Ticket-System für Mieter. Ich möchte den nächsten Schritt machen und ein Büro verantworten.',
      'Eine Kanzlei mit zehn Anwälten und eigenen Abläufen ist für mich die richtige Größe. Diskretion und ein klarer Kopf, wenn drei Dinge gleichzeitig brennen, kann ich. Fristenkalender kenne ich noch nicht, das lerne ich gern.',
      'Teilzeit mit 30 Stunden wäre ideal, Beginn ab dem nächsten Monatsersten.'],
     ['Lebenslauf', 'Zwischenzeugnis'],
     ['Tobias Sommer', 'Alaunstraße 60', '01099 Dresden'])],
  CV('a04', 'modern', 2, 'Juliane Fritsch', 'Office-Managerin', 'Loschwitzer Straße 20', '01309 Dresden',
     [row('08/2019', '', 'Assistenz der Geschäftsführung, ab 2022 Office-Managerin', 'Datenfluss GmbH', 'Dresden', '- Wachstum von 18 auf 65 Mitarbeitende begleitet\n- Zwei Umzüge, Dienstleistersteuerung\n- Onboarding, Events bis 80 Personen'),
      row('08/2015', '07/2019', 'Sachbearbeiterin', 'Elektro Großhandel Sachsen', 'Dresden', '')],
     [row('2012', '2015', 'Ausbildung Kauffrau für Büromanagement', 'IHK Dresden', 'Dresden', '')],
     [['Organisation', 5], ['Dienstleistersteuerung', 4], ['Office-Programme', 5], ['Vorkontierung', 3]],
     [DE, ['Englisch', 'B2']], 'Kanu, Gärtnern'),
  ['Konkrete Beispiele für Organisiertes nennen.', 'Größe des Büros oder Teams angeben.', 'Zeigen, wo du Strukturen aufgebaut hast.'],
  ['„Ich bin ein Organisationstalent“ ohne Beleg.', 'Nur Telefon und Post erwähnen.', 'Die Stelle mit Sekretariat gleichsetzen.'],
  ['Welche Strukturen haben Sie im Büro aufgebaut?', 'Wie priorisieren Sie, wenn drei Leute gleichzeitig etwas wollen?', 'Wie gehen Sie mit Dienstleistern um, die nicht liefern?', 'Wie behalten Sie Budgets im Blick?'],
  [Q('Office-Manager oder Assistenz der Geschäftsführung?', 'Office-Manager kümmern sich um das ganze Büro, Assistenz um eine oder wenige Führungskräfte. In kleinen Firmen ist es oft dieselbe Person. Lies die Aufgaben in der Anzeige genau.')],
  ['assistenz-geschaeftsfuehrung', 'kauffrau-bueromanagement', 'empfangsmitarbeiter', 'teamleiter'],
  en=EN('office-manager', 'Office manager', 'office manager office administrator workplace operations facilities startup',
        'Running the office – suppliers, onboarding, events and more.',
        'Office manager cover letter examples: an experienced assistant taking on a growing office and a receptionist stepping up, plus a ready CV with placeholder portrait.',
        'Office managers keep everything running: suppliers, travel, events, onboarding, often finance admin and HR support. Show what you organised and how many people relied on it.',
        ['Office or administrative experience', 'Organisation and overview', 'Confident with office software', 'Friendly but firm with suppliers', 'Discretion'],
        [L('Assistant who grew with the company', 'erfahren', 'Office manager',
           T('Brightline Software Ltd', 'f', 'Shah', '45 Deansgate', 'Manchester M3 2AY'),
           ['when I joined my current employer there were 18 of us on one floor. There are now 65 across two sites, and I ran both moves, set up the kitchen, negotiated the cleaning contract and built a welcome pack that every new starter finds on their desk on day one.',
            'I have eleven years in office administration and executive support. Coding invoices, booking travel, planning a Christmas party for 80 and keeping the directors free to do their jobs are part of my normal week. I would like to join a company that, like yours, is growing and needs someone to build structure.'],
           ['CV', 'References']),
         L('Receptionist stepping up', 'erfahren', 'Office manager (part time)',
           T('Weber Solicitors', 'm', 'Weber', '2 King Street', 'Manchester M2 4LQ'),
           ['four years on reception in a co-working building have given me far more than my job description: room bookings, maintenance contracts, supplies, and the ticket system for tenants. I would now like to run an office myself.',
            'A firm of ten solicitors is the right size for me. I am discreet and calm when three things go wrong at once. I have not managed a deadline diary yet, and I am keen to learn.'],
           ['CV', 'Reference'],
           ['Tom Fletcher', '60 Oldham Street', 'Manchester M4 1LE'])],
        CV('a04', 'modern', 2, 'Julia Fisher', 'Office manager', '20 Wilmslow Road', 'Manchester M14 5TQ',
           [row('08/2019', '', 'Executive assistant, office manager from 2022', 'Dataflow Ltd', 'Manchester', '- Supported growth from 18 to 65 staff\n- Two office moves, supplier management\n- Onboarding, events up to 80 people'),
            row('08/2015', '07/2019', 'Administrator', 'Northern Wholesale', 'Salford', '')],
           [row('2013', '2015', 'Business administration diploma', 'Manchester College', 'Manchester', '')],
           [['Organisation', 5], ['Supplier management', 4], ['Office software', 5], ['Invoice coding', 3]],
           [['English', 'native'], ['German', 'B1']], 'Canoeing, gardening'),
        ['Give concrete examples of what you organised.', 'Say how big the office or team was.', 'Show where you built structure.'],
        ['Call yourself “highly organised” without proof.', 'Only mention phones and post.', 'Treat the role as a secretary job.'],
        ['What structures have you built in an office?', 'How do you prioritise when three people need something now?', 'How do you deal with suppliers who do not deliver?', 'How do you keep budgets under control?'],
        [Q('Office manager or executive assistant?', 'Office managers look after the whole office; executive assistants support one or a few leaders. In small companies it is often the same person – read the duties in the advert carefully.')]))

J('recruiter', 'buero', 'Recruiter/in',
  'recruiter recruiterin personalgewinnung talent acquisition personalberatung hr recruiting bewerbung',
  'Personalgewinnung im Unternehmen oder in der Personalberatung.',
  'Bewerbung als Recruiter/in: Muster-Anschreiben für erfahrene Recruiterin, Quereinsteiger aus dem Vertrieb und Personalsachbearbeiterin, mit Lebenslauf und Fragen.',
  'Recruiter finden passende Menschen für offene Stellen: Anzeigen schreiben, Kandidaten ansprechen, Gespräche führen, Fachbereiche beraten. Gefragt sind Gespür für Menschen, Ausdauer und Zahlenverständnis – Time-to-hire und Quellen gehören dazu. Erzähl von Stellen, die du besetzt hast.',
  ['Erfahrung in Personalgewinnung oder Vertrieb', 'Gesprächsführung und Menschenkenntnis', 'Active Sourcing in Netzwerken', 'Kennzahlen im Blick', 'Kenntnis im Arbeitsrecht (AGG)'],
  [L('Recruiterin aus der Personalberatung wechselt ins Unternehmen', 'erfahren', 'Recruiterin (Inhouse)',
     T('Medizintechnik Rhein GmbH', 'm', 'Schulz', 'Kaiserswerther Straße 80', '40477 Düsseldorf'),
     ['in der Personalberatung habe ich vier Jahre lang Ingenieure und Techniker für Mittelständler gesucht, im Schnitt 25 Besetzungen im Jahr. Was mir dabei gefehlt hat, ist der Blick danach: Wie geht es den Leuten nach einem Jahr? Inhouse kann ich das begleiten.',
      'Meine Stärke ist die Direktansprache von Fachkräften, die eigentlich gar nicht wechseln wollen. Ich verstehe genug von Technik, um mit einem Elektroingenieur über seine Arbeit zu reden, ohne mich zu blamieren. Ihre Firma wächst und sucht laut Karriereseite 30 Leute in Entwicklung und Produktion. Da möchte ich helfen.',
      'Eintritt wäre zum 1. April möglich.'],
     ['Lebenslauf', 'Arbeitszeugnis', 'Zertifikat Eignungsdiagnostik']),
   L('Vertriebler wechselt ins Recruiting', 'quereinstieg', 'Junior Recruiter',
     T('Personalberatung Westfalen Talent', 'f', 'Krause', 'Königsallee 50', '40212 Düsseldorf'),
     ['sechs Jahre Außendienst im Getränkehandel haben mir beigebracht, wie man Menschen anruft, die keinen Anruf erwartet haben. Im letzten Jahr habe ich zwei Bekannte für offene Stellen bei meinem Arbeitgeber gewonnen und gemerkt: Menschen zusammenzubringen macht mir mehr Spaß als Kisten zu verkaufen.',
      'Ich habe einen Weiterbildungskurs Recruiting abgeschlossen und kenne die Grundlagen des AGG. Telefonieren, Netzwerken und Hartnäckigkeit sind meine Stärken; das Fachliche lerne ich in Ihrem Team.'],
     ['Lebenslauf', 'Zertifikat Recruiting', 'Arbeitszeugnis'],
     ['Marc Hoffmann', 'Bilker Allee 30', '40219 Düsseldorf'])],
  CV('a09', 'modern', 2, 'Nadja Ilić', 'Recruiterin', 'Nordstraße 70', '40477 Düsseldorf',
     [row('03/2022', '', 'Personalberaterin', 'Technik Personal Rhein-Ruhr', 'Düsseldorf', '- Rund 25 Besetzungen pro Jahr (Ingenieure, Techniker)\n- Direktansprache, Interviews, Kundenberatung'),
      row('10/2019', '02/2022', 'Personalreferentin (Elternzeitvertretung, anschließend befristet)', 'Logistik West GmbH', 'Neuss', '')],
     [row('2015', '2019', 'Psychologie (B. Sc.)', 'Heinrich-Heine-Universität', 'Düsseldorf', '')],
     [['Direktansprache', 5], ['Interviewführung', 4], ['Eignungsdiagnostik', 4], ['Kennzahlen', 3]],
     [DE, ['Serbisch', 'native'], ['Englisch', 'C1']], 'Laufen, Fotografie'),
  ['Besetzungen mit Zahlen nennen.', 'Bereich und Zielgruppen angeben.', 'Zeigen, dass du Kandidaten fair behandelst.'],
  ['Nur „Ich bin ein People-Person“.', 'Kennzahlen weglassen.', 'Vertrauliches aus Kundenprojekten nennen.'],
  ['Wie sprechen Sie einen Kandidaten an, der nicht wechseln will?', 'Wie messen Sie Recruiting-Erfolg?', 'Was beachten Sie nach dem AGG?', 'Wie gehen Sie mit einem Fachbereich um, der zu viel verlangt?'],
  [Q('Wie komme ich ohne HR-Studium ins Recruiting?', 'Viele Recruiter kommen aus Vertrieb, Kundenservice oder Psychologie. Ein Kurs zu Recruiting und Arbeitsrecht und erste Erfahrungen, etwa mit Mitarbeiterempfehlungen, sind ein guter Start.')],
  ['personalsachbearbeiter', 'werkstudent-personal', 'aussendienst', 'teamleiter'],
  en=EN('recruiter', 'Recruiter', 'recruiter talent acquisition in-house recruitment consultant hr sourcing',
        'In-house or agency – finding the right people for the right roles.',
        'Recruiter cover letter examples: an agency recruiter moving in-house and a sales professional switching to recruitment, plus a ready CV with placeholder portrait.',
        'Recruiters find the right people for open roles: writing adverts, sourcing, interviewing, advising hiring managers. Say how many roles you have filled and in which areas, and show that you treat candidates fairly.',
        ['Experience in recruitment or sales', 'Interviewing and judgement', 'Sourcing on professional networks', 'Comfort with metrics', 'Knowledge of equality law'],
        [L('Agency recruiter moving in-house', 'erfahren', 'In-house recruiter',
           T('Meridian Medical Devices', 'm', 'Shaw', '80 Aztec West', 'Bristol BS32 4TD'),
           ['four years at an engineering recruitment agency have meant around 25 placements a year, mostly engineers and technicians for mid-sized manufacturers. What I missed was seeing how people were doing a year later. In-house, I can.',
            'My strength is approaching specialists who are not looking to move. I understand enough engineering to talk about someone’s work without embarrassing myself. Your careers page lists thirty open roles in development and production, and I would like to help fill them.'],
           ['CV', 'References']),
         L('Sales professional moving into recruitment', 'quereinstieg', 'Trainee recruitment consultant',
           T('Westgate Talent Partners', 'f', 'Clarke', '50 Queen Square', 'Bristol BS1 4LH'),
           ['six years of field sales have taught me how to call people who were not expecting my call. Last year I introduced two friends to open roles at my company, and I realised that matching people to jobs suits me better than selling drinks.',
            'I have completed a short recruitment course and know the basics of equality law. Phone work, networking and persistence are my strengths; the specialist knowledge I will learn in your team.'],
           ['CV', 'Course certificate'],
           ['Mark Hill', '30 Gloucester Road', 'Bristol BS7 8AE'])],
        CV('a09', 'modern', 2, 'Nadia Ilic', 'Recruiter', '70 Cheltenham Road', 'Bristol BS6 5RL',
           [row('03/2022', '', 'Recruitment consultant', 'Technical Talent West', 'Bristol', '- Around 25 placements a year\n- Direct sourcing, interviews, client advice'),
            row('10/2019', '02/2022', 'HR assistant', 'Western Logistics', 'Avonmouth', '')],
           [row('2015', '2019', 'BSc Psychology', 'University of the West of England', 'Bristol', '')],
           [['Sourcing', 5], ['Interviewing', 4], ['Assessment', 4], ['Metrics', 3]],
           [['English', 'native'], ['Serbian', 'native']], 'Running, photography'),
        ['Give placement numbers.', 'Name your sectors and candidate groups.', 'Show you treat candidates fairly.'],
        ['Call yourself a “people person” and stop there.', 'Leave out metrics.', 'Mention confidential client details.'],
        ['How do you approach someone who is not looking?', 'How do you measure recruitment success?', 'What does equality law mean in practice?', 'How do you handle a hiring manager with unrealistic demands?'],
        [Q('Can I move into recruitment without an HR degree?', 'Yes. Many recruiters come from sales, customer service or psychology. A short course on recruitment and employment law plus some referral experience is a good start.')]))

J('empfangsmitarbeiter', 'buero', 'Empfangsmitarbeiter/in (Büro, Praxis, Kanzlei)',
  'empfang empfangsmitarbeiterin empfangskraft rezeption büro telefonzentrale front office empfangsdame bewerbung',
  'Erster Eindruck im Unternehmen – Telefon, Besucher, Post.',
  'Bewerbung als Empfangsmitarbeiter/in in Unternehmen, Kanzlei oder Praxis: Muster-Anschreiben für Wiedereinsteigerin, Hotelfachmann und Schulabgängerin, mit Lebenslauf.',
  'Am Empfang bist du die Stimme und das Gesicht der Firma. Du nimmst Anrufe an, begrüßt Besucher, verteilst Post, buchst Räume und behältst den Überblick, wenn alles gleichzeitig passiert. Freundlichkeit, ein gutes Gedächtnis für Namen und Ruhe sind wichtiger als jeder Abschluss.',
  ['Freundliches, gepflegtes Auftreten', 'Telefonroutine', 'Organisation von Räumen, Post, Besuchern', 'Englisch, oft gewünscht', 'Diskretion'],
  [L('Hotelfachmann wechselt an den Firmenempfang', 'quereinstieg', 'Empfangsmitarbeiter (Vollzeit)',
     T('Ingenieurgesellschaft Sander & Partner', 'f', 'Sander', 'Hafenstraße 2', '48153 Münster'),
     ['nach sieben Jahren an Hotelrezeptionen möchte ich in feste Tagdienste wechseln, ohne meinen Beruf aufzugeben. Begrüßen, Fragen beantworten, Besucher dorthin bringen, wo sie hinwollen, das kann ich im Schlaf, und das sage ich nach vielen Nachtschichten nicht leichtfertig.',
      'Im Hotel habe ich täglich bis zu 150 Gäste ein- und ausgecheckt, Beschwerden aufgenommen und Konferenzräume vorbereitet. Englisch spreche ich fließend, Spanisch gut. Ihr Unternehmen empfängt viele internationale Kunden, das passt.',
      'Ab dem 1. März stehe ich zur Verfügung.'],
     ['Lebenslauf', 'Abschlusszeugnis Hotelfachmann', 'Arbeitszeugnis']),
   L('Schulabgängerin mit Praxiserfahrung', 'berufseinstieg', 'Empfangskraft (Arztpraxis, Teilzeit)',
     T('Orthopädie Gemeinschaftspraxis am Dom', 'm', 'Dr. Albers', 'Domplatz 5', '48143 Münster'),
     ['Telefonieren mit Fremden fand ich früher schwierig. Dann habe ich zwei Jahre lang im Schreibwarenladen meiner Tante ausgeholfen und gemerkt, dass ich es kann, sobald ich weiß, was ich sagen soll. Heute macht es mir Spaß.',
      'Im Sommer habe ich das Fachabitur Gesundheit und Soziales abgeschlossen. Im Praktikum bei einem Hausarzt habe ich am Empfang Termine vergeben, Versichertenkarten eingelesen und Patienten in den Wartebereich begleitet. Ich möchte zunächst in Teilzeit arbeiten und nebenbei die Ausbildung zur MFA vorbereiten.'],
     ['Lebenslauf', 'Fachabiturzeugnis', 'Praktikumsbescheinigung'],
     ['Lena Hölscher', 'Hammer Straße 30', '48153 Münster'])],
  CV('a05', 'classic', 1, 'Rafael Costa', 'Hotelfachmann, Rezeptionist', 'Wolbecker Straße 60', '48155 Münster',
     [row('05/2019', '', 'Rezeptionist', 'Hotel am Aasee', 'Münster', '- Check-in und -out, bis 150 Gäste täglich\n- Konferenzräume vorbereiten\n- Beschwerdemanagement'),
      row('08/2016', '04/2019', 'Hotelfachmann', 'Parkhotel Osnabrück', 'Osnabrück', '')],
     [row('2013', '2016', 'Ausbildung Hotelfachmann', 'Parkhotel Osnabrück', 'Osnabrück', '')],
     [['Gästeempfang', 5], ['Telefon', 5], ['Raumorganisation', 4], ['Englisch', 4]],
     [['Portugiesisch', 'native'], DE, ['Englisch', 'C1'], ['Spanisch', 'B2']], 'Fußball, Kochen'),
  ['Telefon- und Besuchererfahrung nennen.', 'Sprachen angeben.', 'Arbeitszeitwunsch klarmachen.'],
  ['Den Empfang als „nur Telefon“ beschreiben.', 'Fehler im Anschreiben.', 'Ungepflegtes Foto.'],
  ['Wie begrüßen Sie einen Besucher, der zu früh kommt?', 'Was tun Sie, wenn drei Telefone gleichzeitig klingeln?', 'Wie gehen Sie mit unhöflichen Anrufern um?', 'Wie merken Sie sich Namen?'],
  [Q('Brauche ich eine kaufmännische Ausbildung?', 'Nicht immer. Viele Empfangskräfte kommen aus Hotel, Handel oder Praxis. Wichtig sind Auftreten, Telefonroutine und Organisation.')],
  ['rezeptionist', 'office-manager', 'callcenter-agent', 'kauffrau-bueromanagement'])
